package ama.transcript;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task11AcceptanceBindingTest {
 Map<String,Object> manifest(){var m=new TreeMap<String,Object>();m.put("schema","ama.knowledge-publication-manifest.v1");for(String k:List.of("publicationId","confirmationId","meetingId"))m.put(k,"12345678-1234-4234-8234-123456789abc");for(String k:List.of("providerId","storeInstanceId","clientId","delegationKeyId","assertionKeyId","requesterId","libraryId","folderId"))m.put(k,k);for(String k:List.of("logicalRequestHash","payloadSha256","archiveIndexSha256"))m.put(k,"a".repeat(64));m.put("businessKey",m.get("publicationId")+":"+m.get("confirmationId"));m.put("businessVersion",13L);m.put("cancelEpoch",0L);m.put("executionNo",1L);m.put("submissionNo",1L);m.put("priorProofs",List.of());m.put("renderArtifact",Map.of("version","render-v1","sha256","b".repeat(64)));m.put("executionRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",m.get("logicalRequestHash"),"executionNo",1L,"priorProofs",List.of()),budget())));return m;}
 TranscriptAcquisitionBudget.Ledger budget(){return budget(false);}
 TranscriptAcquisitionBudget.Ledger budget(boolean cancelled){return new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,33554432,128,256,256).ledger(new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,16777216,64,128,128,2000000,128,255,4194304,4194304,16777216,65536,64,100000,500000),new ama.contract.MinutesContracts.CanonicalBudget(67108864,128,4000000,4194304,16777216),()->cancelled);}
 @Test void boundProducerSeparatesReceiptIdentitiesWhileLegacyAlgorithmIsStable(){var m=manifest();String old=JdbcPublicationService.spec(m,budget()).producerKey();assertEquals("2203b62b7bfe3cd92e512d7312b35578db040a6d720109528c7142aa645c04ce",old,"Frozen legacy producer.v1 public vector");var b=Map.of("schema","ama.publication-command-acceptance.v1","operation","PUBLICATION_SUBMIT","receiptScopeHash","c".repeat(64),"requestHash","d".repeat(64));m.put("acceptanceBinding",b);var first=assertDoesNotThrow(()->JdbcPublicationService.spec(m,budget()).producerKey(),"New strict acceptance binding must be supported");assertNotEquals(old,first);var next=new TreeMap<String,Object>(b);next.put("receiptScopeHash","e".repeat(64));m.put("acceptanceBinding",next);assertNotEquals(first,JdbcPublicationService.spec(m,budget()).producerKey());m.remove("acceptanceBinding");assertEquals(old,JdbcPublicationService.spec(m,budget()).producerKey());}
 @Test void originalWireBudgetAndCancellationRemainDistinct(){String valid=new String(ControlledKnowledgeClient.canonical(manifest()),java.nio.charset.StandardCharsets.UTF_8);var cancelled=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read(valid,budget(true)));assertEquals(ama.contract.MinutesContracts.FailureCode.CANCELLED,cancelled.code());var large=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read("x".repeat(65537),budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,large.code());}
 @Test void malformedOriginalWireIsUnavailable(){var f=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read("{",budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,f.code());}
 @Test void malformedStoredBindingDigestIsUnavailableRatherThanClientInvalid(){var m=manifest();m.put("acceptanceBinding",Map.of("schema","ama.publication-command-acceptance.v1","operation","PUBLICATION_SUBMIT","receiptScopeHash","C".repeat(64),"requestHash","d".repeat(64)));var f=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.validate(m,budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,f.code());}
 @Test void nullStoredAcceptanceOperationIsProvenanceUnavailable(){var m=manifest();var binding=new TreeMap<String,Object>();binding.put("schema","ama.publication-command-acceptance.v1");binding.put("operation",null);binding.put("receiptScopeHash","c".repeat(64));binding.put("requestHash","d".repeat(64));m.put("acceptanceBinding",binding);String stored=new String(ControlledKnowledgeClient.canonical(m),java.nio.charset.StandardCharsets.UTF_8);var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read(stored,budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,failure.code());}
 @Test void partialOrForeignAcceptanceBindingIsRejected(){var m=manifest();m.put("acceptanceBinding",Map.of("operation","PUBLICATION_SUBMIT"));assertThrows(RuntimeException.class,()->PublicationManifest.validate(m,budget()));}
 @Test void exactRetryBindingIsStrictAndSeparatesExistingProducerIdentity(){var m=manifest();m.put("acceptanceBinding",Map.of("schema","ama.publication-command-acceptance.v1","operation","PUBLICATION_SUBMIT","receiptScopeHash","c".repeat(64),"requestHash","d".repeat(64)));String existing=JdbcPublicationService.spec(m,budget()).producerKey();var binding=new TreeMap<String,Object>((Map<String,Object>)m.get("acceptanceBinding"));binding.put("operation","PUBLICATION_ZERO_EFFECT_RETRY");m.put("acceptanceBinding",binding);String retry=assertDoesNotThrow(()->JdbcPublicationService.spec(m,budget()).producerKey());assertNotEquals(existing,retry);String wire=new String(ControlledKnowledgeClient.canonical(m),java.nio.charset.StandardCharsets.UTF_8);var parsed=PublicationManifest.read(wire,budget());assertEquals(binding,parsed.get("acceptanceBinding"));assertEquals(retry,JdbcPublicationService.spec(parsed,budget()).producerKey());assertEquals(wire,new String(ControlledKnowledgeClient.canonical(parsed),java.nio.charset.StandardCharsets.UTF_8));binding.put("operation","PUBLICATION_RETRY_UNKNOWN");var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.validate(m,budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,failure.code());}
 @Test void highestCanonicalCounterIsRepresentableButLongMaxIsRejected(){for(long value:List.of(9223372036854775806L,Long.MAX_VALUE)){var m=manifest();for(String field:List.of("businessVersion","cancelEpoch","executionNo","submissionNo"))m.put(field,value);m.put("executionRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",m.get("logicalRequestHash"),"executionNo",value,"priorProofs",List.of()),budget())));String wire=new String(ControlledKnowledgeClient.canonical(m),java.nio.charset.StandardCharsets.UTF_8);if(value==Long.MAX_VALUE){var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read(wire,budget()));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,failure.code());}else{assertDoesNotThrow(()->PublicationManifest.validate(m,budget()));assertEquals(value,((Number)PublicationManifest.read(wire,budget()).get("executionNo")).longValue());}}}
}
